size_t process_note_headers(struct magic_set *ms, void *vbuf, size_t offset,
    size_t size, int clazz, int swap, size_t align, int *flags,
    uint16_t *notecount) {
  uint8_t *buf = (uint8_t *)vbuf;
  size_t new_offset = offset;
  uint16_t remaining_notes = *notecount;

  while (remaining_notes > 0 && new_offset + align <= size) {
    uint32_t name_size, desc_size, type;

    /* Read note header fields based on class and swap */
    if (clazz == MSB) {
      if (new_offset + sizeof(uint32_t) * 2 + sizeof(uint16_t) > size)
        break;
      name_size = le32dec((uint8_t *)(buf + new_offset));
      desc_size = le32dec((uint8_t *)(buf + new_offset + sizeof(uint32_t)));
      type = le32dec((uint8_t *)(buf + new_offset + 2 * sizeof(uint32_t)));
    } else {
      if (new_offset + sizeof(uint32_t) * 2 + sizeof(uint16_t) > size)
        break;
      name_size = be32dec((uint8_t *)(buf + new_offset));
      desc_size = be32dec((uint8_t *)(buf + new_offset + sizeof(uint32_t)));
      type = be32dec((uint8_t *)(buf + new_offset + 2 * sizeof(uint32_t)));
    }

    /* Validate note header sizes */
    if (name_size > size - new_offset - 3 * sizeof(uint32_t)) {
      break;
    }

    /* Align the start of the note descriptor */
    size_t desc_start = new_offset + 3 * sizeof(uint32_t) + name_size;
    desc_start = ALIGN(desc_start, align);

    if (desc_start + desc_size > size) {
      break;
    }

    /* Process note based on type */
    if (type == NOTE_TYPE_NETBSD) {
      *flags |= NOTE_NETBSD_PROCESSED;
    }

    /* Update offset and remaining note count */
    new_offset = desc_start + desc_size;
    remaining_notes--;
  }

  *notecount = remaining_notes;
  return (new_offset >= size) ? size : new_offset;
}

size_t process_note_headers(struct magic_set *ms, void *vbuf, size_t offset, size_t size, int clazz, int swap, size_t align, int *flags, uint16_t *notecount) {
    uint8_t *buf = (uint8_t *)vbuf;
    size_t new_offset = offset;
    size_t note_size;

    while (new_offset < size && *notecount > 0) {
        uint32_t note_type;
        uint32_t note_desc_size;

        if (clazz == MSB) {
            if (swap) {
                note_type = GETBIG32(buf + new_offset);
                note_desc_size = GETBIG32(buf + new_offset + 4);
            } else {
                note_type = GETORD32(buf + new_offset);
                note_desc_size = GETORD32(buf + new_offset + 4);
            }
        } else {
            note_type = GETLIL32(buf + new_offset);
            note_desc_size = GETLIL32(buf + new_offset + 4);
        }

        if (note_type == NT_NETBSD) {
            *flags |= NOTE_NETBSD;
        }

        note_size = align * ((new_offset + align) / align);
        if (note_size + note_desc_size > size - new_offset) {
            break;
        }

        new_offset += note_size + note_desc_size;
        (*notecount)--;
    }

    return new_offset;
}

size_t process_note_headers(struct magic_set *ms, void *vbuf, size_t offset, size_t size, int clazz, int swap, size_t align, int *flags, uint16_t *notecount) {
    uint8_t *buf = (uint8_t *)vbuf;
    size_t new_offset = offset;

    while (new_offset + align <= size && *notecount > 0) {
        uint32_t name_size, desc_size, type;

        /* Align the offset according to the class */
        new_offset = ((new_offset + align) / align) * align;

        if (new_offset + sizeof(name_size) + sizeof(desc_size) + sizeof(type) > size) {
            break;
        }

        if (clazz == MSB) {
            name_size = getbe32(buf + new_offset);
            desc_size = getbe32(buf + new_offset + sizeof(name_size));
            type = getbe32(buf + new_offset + sizeof(name_size) + sizeof(desc_size));
        } else {
            name_size = getle32(buf + new_offset);
            desc_size = getle32(buf + new_offset + sizeof(name_size));
            type = getle32(buf + new_offset + sizeof(name_size) + sizeof(desc_size));
        }

        /* Skip name (not used in this case) */
        new_offset += sizeof(name_size) + sizeof(desc_size) + sizeof(type);

        /* Check if the descriptor is beyond the buffer */
        if (new_offset + desc_size > size) {
            break;
        }

        if (type == NT_NETBSD_CORE) {
            *flags |= NOTE_NETBSD_CORE;
        }

        new_offset += desc_size;
        (*notecount)--;
    }

    return new_offset;
}

size_t process_note_headers(struct magic_set *ms, void *vbuf, size_t offset, size_t size, int clazz, int swap, size_t align, int *flags, uint16_t *notecount) {
    uint16_t note_type;
    size_t note_size;
    size_t entry_size;
    size_t end = size;
    uint16_t *notecount_val = notecount;

    while (*notecount_val > 0 && offset + sizeof(note_type) + sizeof(note_size) <= size) {
        /* Read note type and size */
        if (swap) {
            note_type = swap16(*(uint16_t *)((char *)vbuf + offset));
            note_size = swap32(*(uint32_t *)((char *)vbuf + offset + sizeof(note_type)));
        } else {
            note_type = *(uint16_t *)((char *)vbuf + offset);
            note_size = *(uint32_t *)((char *)vbuf + offset + sizeof(note_type));
        }

        entry_size = sizeof(note_type) + sizeof(note_size) + note_size;
        if (offset + entry_size > size) {
            break;
        }

        /* Process note based on type */
        if (note_type == NT_NETBSD_CORE) {
            *flags |= NOTE_NETBSD_CORE;
        }

        /* Update offset and note count */
        offset += align_value(offset, align) + entry_size;
        (*notecount_val)--;
    }

    return (offset < size ? offset : size);
}

size_t process_note_headers(struct magic_set *ms, void *vbuf, size_t offset,
    size_t size, int clazz, int swap, size_t align, int *flags,
    uint16_t *notecount) {
  uint8_t *buf = (uint8_t *)vbuf;
  size_t new_offset = offset;
  size_t limit = size;
  uint16_t note_type;

  while (new_offset < limit && *notecount > 0) {
    if (new_offset + sizeof(uint32_t) + sizeof(uint32_t) > limit) {
      break;
    }

    uint32_t note_name_size;
    uint32_t note_desc_size;
    uint32_t note_total_size;

    if (swap) {
      note_name_size = get_swapped_32(ms, &buf[new_offset]);
      note_desc_size = get_swapped_32(ms, &buf[new_offset + sizeof(uint32_t)]);
    } else {
      note_name_size = *(uint32_t *)&buf[new_offset];
      note_desc_size = *(uint32_t *)&buf[new_offset + sizeof(uint32_t)];
    }

    note_total_size = sizeof(uint32_t) * 2 + ((note_name_size + 3) & ~3) +
                      ((note_desc_size + 3) & ~3);

    if (new_offset + note_total_size > limit) {
      break;
    }

    new_offset += sizeof(uint32_t) * 2;

    if (clazz == EM_NETBSD) {
      if (new_offset + sizeof(uint16_t) > limit) {
        break;
      }
      note_type = *(uint16_t *)&buf[new_offset];
      new_offset += sizeof(uint16_t);

      if (note_type == NT_NETBSD) {
        *flags |= NOTE_PROCESSED;
      }
    }

    new_offset = (new_offset + align - 1) & ~(align - 1);
    (*notecount)--;
  }

  return new_offset;
}
